using System.Collections.Concurrent;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
var b=WebApplication.CreateBuilder(args); b.WebHost.UseUrls("http://127.0.0.1:5198"); b.Services.AddSingleton<State>(); b.Services.AddSingleton<Traces>(); b.Services.AddSingleton<ProcessManager>(); b.Services.AddHttpClient("remote").ConfigurePrimaryHttpMessageHandler(()=>new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false}); var app=b.Build(); app.UseDefaultFiles();app.UseStaticFiles();
app.MapGet("/api/settings",(State s)=>s.View());
app.MapPut("/api/settings",(Settings x,State s)=>{s.AdbPath=x.AdbPath??s.AdbPath;s.ActiveProfileId=x.ActiveProfileId??s.ActiveProfileId;s.Save();return s.View();});
app.MapPost("/api/profiles",(Profile x,State s)=>{if(!UrlOk(x.BaseUrl)||!UrlOk(x.SwaggerUrl))return Results.BadRequest("Invalid URL");s.Upsert(x);return Results.Ok(s.View());});
app.MapDelete("/api/profiles/{id}",(string id,State s)=>{s.Profiles.RemoveAll(p=>p.Id==id);s.ActiveProfileId=s.Profiles.FirstOrDefault()?.Id??"";s.Save();return s.View();});
app.MapGet("/api/swagger/{id}",async(string id,State s,IHttpClientFactory factory)=>{var p=s.Profiles.FirstOrDefault(x=>x.Id==id);if(p==null)return Results.NotFound();try{var r=await factory.CreateClient("remote").GetAsync(p.SwaggerUrl);return r.IsSuccessStatusCode?Results.Content(await r.Content.ReadAsStringAsync(),"application/json"):Results.Problem($"HTTP {(int)r.StatusCode}");}catch(Exception e){return Results.Problem(e.Message);}});
app.MapPost("/api/request",async(RequestInput x,State s,IHttpClientFactory f,Traces t)=>{var p=s.Profiles.FirstOrDefault(y=>y.Id==x.ProfileId);if(p==null)return Results.NotFound();if(!Uri.TryCreate(p.BaseUrl,UriKind.Absolute,out var root)||!Uri.TryCreate(root,x.Path.TrimStart('/'),out var url)||root.Host!=url.Host||root.Port!=url.Port||root.Scheme!=url.Scheme||!url.AbsolutePath.StartsWith(root.AbsolutePath.TrimEnd('/')+"/",StringComparison.OrdinalIgnoreCase))return Results.BadRequest("URL outside configured base");if(x.Method.ToUpperInvariant() is not ("GET" or "POST" or "PUT" or "PATCH" or "DELETE" or "HEAD"))return Results.BadRequest("Unsupported method");var id=ActivityTraceId.CreateRandom().ToString();var watch=Stopwatch.StartNew();try{using var req=new HttpRequestMessage(new HttpMethod(x.Method),url);req.Headers.TryAddWithoutValidation("X-Correlation-ID",id);req.Headers.TryAddWithoutValidation("traceparent",$"00-{id}-{ActivitySpanId.CreateRandom()}-01");t.Add(new TraceEvent(id,DateTimeOffset.UtcNow,"DevBridge","HTTP request started","info",null));if(x.Headers!=null)foreach(var h in x.Headers){if(h.Key.Equals("Host",StringComparison.OrdinalIgnoreCase)||h.Key.Equals("X-Correlation-ID",StringComparison.OrdinalIgnoreCase)||h.Key.Equals("Content-Length",StringComparison.OrdinalIgnoreCase))continue;if(!Regex.IsMatch(h.Key,@"^[A-Za-z0-9-]+$")||h.Value.Contains("\r")||h.Value.Contains("\n"))continue;req.Headers.TryAddWithoutValidation(h.Key,h.Value);}if(x.Method is not ("GET" or "HEAD")&&!string.IsNullOrWhiteSpace(x.Body))req.Content=new StringContent(x.Body,Encoding.UTF8,"application/json");if(!req.Headers.Contains("Authorization")&&!string.IsNullOrWhiteSpace(p.Token))req.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",p.Token);using var resp=await f.CreateClient("remote").SendAsync(req);var body=await resp.Content.ReadAsStringAsync();t.Add(new TraceEvent(id,DateTimeOffset.UtcNow,"DevBridge",$"{x.Method} {url.AbsolutePath} → {(int)resp.StatusCode} ({watch.ElapsedMilliseconds}ms)",resp.IsSuccessStatusCode?"success":"error",null));return Results.Ok(new{status=(int)resp.StatusCode,durationMs=watch.ElapsedMilliseconds,body=body.Length>2000000?body[..2000000]:body,correlationId=id});}catch(Exception e){t.Add(new TraceEvent(id,DateTimeOffset.UtcNow,"DevBridge",e.Message,"error",null));return Results.Problem(e.Message);}});
app.MapGet("/api/adb/status",async(State s)=>{try{var x=await Adb.Run(s.AdbPath,"version");return new{ok=x.code==0,output=x.output};}catch(Exception e){return new{ok=false,output=e.Message};}});
app.MapGet("/api/adb/devices",async(State s)=>{try{var x=await Adb.Run(s.AdbPath,"devices -l");return x.output.Split('\n').Skip(1).Where(y=>Regex.IsMatch(y,@"^\S+\s+device\b")).Select(y=>Regex.Match(y,@"^\S+").Value).ToArray();}catch{return [];}});
app.MapGet("/api/logcat",async(HttpContext ctx,State s,string? device,string? package)=>{ctx.Response.ContentType="text/event-stream";ctx.Response.Headers.CacheControl="no-cache";if(device!=null&&!Regex.IsMatch(device,@"^[\w.:-]+$"))return;if(package!=null&&!Regex.IsMatch(package,@"^[\w.]+$"))return;using var proc=new Process{StartInfo=new ProcessStartInfo(s.AdbPath){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true}};if(device!=null){proc.StartInfo.ArgumentList.Add("-s");proc.StartInfo.ArgumentList.Add(device);}proc.StartInfo.ArgumentList.Add("logcat");proc.StartInfo.ArgumentList.Add("-v");proc.StartInfo.ArgumentList.Add("threadtime");try{proc.Start();string? pid=null;var checkedAt=DateTimeOffset.MinValue;while(!ctx.RequestAborted.IsCancellationRequested){var line=await proc.StandardOutput.ReadLineAsync(ctx.RequestAborted);if(line==null)break;var m=Regex.Match(line,@"^\d\d-\d\d\s+\d\d:\d\d:\d\d\.\d+\s+(\d+)\s+\d+\s+([VDIWEF])\s+([^:]+):\s?(.*)$");if(package!=null){if(DateTimeOffset.UtcNow-checkedAt>TimeSpan.FromSeconds(3)){var r=await Adb.Run(s.AdbPath,(device==null?"":"-s "+device+" ")+"shell pidof "+package);pid=r.output.Trim().Split(' ',StringSplitOptions.RemoveEmptyEntries).FirstOrDefault();checkedAt=DateTimeOffset.UtcNow;}if(!m.Success||m.Groups[1].Value!=pid)continue;}var item=m.Success?new{level=m.Groups[2].Value,tag=m.Groups[3].Value.Trim(),text=m.Groups[4].Value,raw=line}:new{level="I",tag="system",text=line,raw=line};await ctx.Response.WriteAsync("data: "+JsonSerializer.Serialize(item)+"\n\n",ctx.RequestAborted);await ctx.Response.Body.FlushAsync(ctx.RequestAborted);}}catch(OperationCanceledException){}catch(Exception e){try{await ctx.Response.WriteAsync("data: "+JsonSerializer.Serialize(new{level="E",tag="ADB",text=e.Message,raw=e.Message})+"\n\n");}catch{}}finally{try{if(!proc.HasExited)proc.Kill(true);}catch{}}});
app.MapGet("/api/traces",(Traces t)=>t.Items.Reverse().ToArray());
app.MapPost("/api/traces",(TraceInput x,Traces t)=>{
    if(string.IsNullOrWhiteSpace(x.CorrelationId)||!Regex.IsMatch(x.CorrelationId,@"^[a-zA-Z0-9_-]{1,128}$"))return Results.BadRequest("Invalid trace ID");
    var source=(x.Source??"unknown")[..Math.Min(80,(x.Source??"unknown").Length)];
    var message=(x.Message??"")[..Math.Min(4000,(x.Message??"").Length)];
    var level=x.Level is "error" or "warning" or "success" ? x.Level : "info";
    var data=x.Data is {Length:>20000}?x.Data[..20000]:x.Data;
    var stage=x.Stage is "android-request" or "server-request" or "server-response" or "android-response" ? x.Stage : null;
    var at=x.At is { } supplied && Math.Abs((DateTimeOffset.UtcNow-supplied).TotalMinutes)<10?supplied:DateTimeOffset.UtcNow;
    t.Add(new TraceEvent(x.CorrelationId,at,source,message,level,data,stage));
    return Results.Ok();
});
app.MapGet("/api/processes", (ProcessManager pm) => pm.List());
app.MapGet("/api/processes/{id}/logs", (string id, long? after, ProcessManager pm) => pm.Logs(id, after ?? 0));
app.MapPost("/api/processes", (ManagedProject project, ProcessManager pm) => pm.Save(project, out var error) ? Results.Ok(pm.List()) : Results.BadRequest(error));
app.MapDelete("/api/processes/{id}", (string id, ProcessManager pm) => pm.Remove(id) ? Results.Ok(pm.List()) : Results.BadRequest("Stop the process first"));
app.MapPost("/api/processes/{id}/start", (string id, ProcessManager pm) => { var (ok, message) = pm.Start(id); return ok ? Results.Ok(new { message }) : Results.BadRequest(message); });
app.MapPost("/api/processes/{id}/stop", async (string id, ProcessManager pm) => { var (ok, message) = await pm.Stop(id); return ok ? Results.Ok(new { message }) : Results.BadRequest(message); });
app.MapPost("/api/processes/{id}/restart", async (string id, ProcessManager pm) => { var (ok, message) = await pm.Stop(id); if (!ok) return Results.BadRequest(message); var started = pm.Start(id); return started.ok ? Results.Ok(new { message = started.message }) : Results.BadRequest(started.message); });
app.Lifetime.ApplicationStarted.Register(() => app.Services.GetRequiredService<ProcessManager>().StartAuto());
app.MapFallbackToFile("index.html");if(args.Contains("--open"))_ = Task.Run(async()=>{await Task.Delay(1500);try{Process.Start(new ProcessStartInfo("http://127.0.0.1:5198"){UseShellExecute=true});}catch{}});app.Run();
static bool UrlOk(string x)=>Uri.TryCreate(x,UriKind.Absolute,out var u)&&(u.Scheme=="http"||u.Scheme=="https")&&u.UserInfo=="";
record Profile(string Id,string Name,string BaseUrl,string SwaggerUrl,string? Token);record Settings(string? AdbPath,string? ActiveProfileId);record RequestInput(string ProfileId,string Method,string Path,string? Body,Dictionary<string,string>? Headers=null);record TraceInput(string CorrelationId,string? Source,string? Message,string? Level,string? Data,DateTimeOffset? At=null,string? Stage=null);record TraceEvent(string CorrelationId,DateTimeOffset At,string Source,string Message,string Level,string? Data,string? Stage=null);
class Traces{public ConcurrentQueue<TraceEvent> Items=new();public void Add(TraceEvent x){Items.Enqueue(x);while(Items.Count>1000)Items.TryDequeue(out _);}}
class State{readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DevBridge","settings.json");public string AdbPath="adb";public string ActiveProfileId="local";public List<Profile> Profiles=[];public State(){try{if(File.Exists(path)){using var d=JsonDocument.Parse(File.ReadAllText(path));var root=d.RootElement;AdbPath=root.GetProperty("adbPath").GetString()??"adb";ActiveProfileId=root.GetProperty("activeProfileId").GetString()??"local";foreach(var p in root.GetProperty("profiles").EnumerateArray()){string? token=null;try{var v=p.GetProperty("protectedToken").GetString();if(v!=null&&OperatingSystem.IsWindows())token=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(v),null,DataProtectionScope.CurrentUser));}catch{}Profiles.Add(new(p.GetProperty("id").GetString()??"",p.GetProperty("name").GetString()??"",p.GetProperty("baseUrl").GetString()??"",p.GetProperty("swaggerUrl").GetString()??"",token));}}}catch{}if(Profiles.Count==0)Profiles.Add(new("local","Localhost","http://localhost:5000/","http://localhost:5000/swagger/v1/swagger.json",null));if(AdbPath=="adb"){var sdk=Environment.GetEnvironmentVariable("ANDROID_HOME")??Environment.GetEnvironmentVariable("ANDROID_SDK_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Android","Sdk");var candidate=Path.Combine(sdk,"platform-tools","adb.exe");if(File.Exists(candidate))AdbPath=candidate;}}public object View()=>new{adbPath=AdbPath,activeProfileId=ActiveProfileId,profiles=Profiles.Select(p=>new{p.Id,p.Name,p.BaseUrl,p.SwaggerUrl,hasToken=!string.IsNullOrEmpty(p.Token)})};public void Upsert(Profile x){var i=Profiles.FindIndex(p=>p.Id==x.Id);if(i>=0){if(x.Token==null)x=x with{Token=Profiles[i].Token};Profiles[i]=x;}else Profiles.Add(x);Save();}public void Save(){Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonSerializer.Serialize(new{adbPath=AdbPath,activeProfileId=ActiveProfileId,profiles=Profiles.Select(p=>new{id=p.Id,name=p.Name,baseUrl=p.BaseUrl,swaggerUrl=p.SwaggerUrl,protectedToken=OperatingSystem.IsWindows()&&!string.IsNullOrEmpty(p.Token)?Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(p.Token),null,DataProtectionScope.CurrentUser)):null})}));}}
static class Adb{public static async Task<(int code,string output)> Run(string exe,string args){using var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true}};p.Start();using var c=new CancellationTokenSource(TimeSpan.FromSeconds(8));var a=p.StandardOutput.ReadToEndAsync(c.Token);var b=p.StandardError.ReadToEndAsync(c.Token);await p.WaitForExitAsync(c.Token);return(p.ExitCode,(await a)+(await b));}}
